// Isolated test entry; the production practice runner/input bridge is unchanged.
const {app,BrowserWindow,session,ipcMain}=require('electron'),fs=require('node:fs'),path=require('node:path');
const directory=process.env.FORMNARO_PRACTICE_DIRECTORY,entry=process.env.FORMNARO_AGENT_ENTRY,proof=process.env.FORMNARO_AGENT_PROOF;
if(!directory||!entry||!proof||typeof process.send!=='function')process.exit(125);
app.setPath('userData',path.join(directory,'profile'));app.setPath('sessionData',path.join(directory,'profile'));
global.fetch=async()=>{throw Error('Network is disabled in this practice test.');};
app.whenReady().then(async()=>{
 const errors=[],external=[];
 session.defaultSession.webRequest.onBeforeRequest((d,cb)=>{if(/^https?:/i.test(d.url))external.push(d.url);cb({cancel:/^https?:/i.test(d.url)});});
 const win=new BrowserWindow({show:true,width:1400,height:950,title:'Formnaro · isolierte MCP-Übungsprüfung',webPreferences:{contextIsolation:true,sandbox:true,backgroundThrottling:false,preload:path.resolve(__dirname,'../../preload.cjs'),additionalArguments:['--formnaro-portable-data','--formnaro-practice']}});
 require('../../backend/program-storage.cjs').installProgramStorage(win,{directory:path.join(directory,'data'),cadOnly:true});
 require('../../backend/layouts.cjs').installLayouts(win,{directory:path.join(directory,'layouts')});
 require('../../backend/desktop-ai.cjs').installDesktopAI(win,{settingsFile:path.join(directory,'data/ai-settings.json')});
 ipcMain.handle('cad-speech:online-status',()=>({ok:true,value:{hasKey:false}}));ipcMain.handle('cad-speech:status',()=>({ok:true,value:{available:false}}));
 win.webContents.setWindowOpenHandler(()=>({action:'deny'}));win.webContents.on('will-navigate',e=>e.preventDefault());
 win.webContents.on('console-message',e=>{if(e.level==='error')errors.push(e.message);});
 win.webContents.on('dom-ready',()=>{void win.webContents.executeJavaScript(`document.addEventListener('dragover',()=>{},true);window.__practiceBuildFrames=[];window.__practiceUIBuildFrames=[];window.__practiceInitialTempo=null;new MutationObserver(()=>{const speed=document.getElementById('practice-speed');if(speed&&window.__practiceInitialTempo===null)window.__practiceInitialTempo=speed.defaultValue||speed.value;const count=new Set([...document.querySelectorAll('#object-list [data-root-id]')].filter(n=>n.dataset.path==='[]').map(n=>n.dataset.rootId)).size;if(count>0&&count!==(window.__practiceUIBuildFrames.at(-1)?.count??0))window.__practiceUIBuildFrames.push({count,time:performance.now()});}).observe(document,{childList:true,subtree:true});new MutationObserver(()=>{const c=document.getElementById('practice-caption');if(c?.textContent.startsWith('Live-Aufbau')&&window.__practiceBuildFrames.at(-1)?.caption!==c.textContent)window.__practiceBuildFrames.push({caption:c.textContent,time:performance.now()});}).observe(document,{childList:true,subtree:true,characterData:true});window.__practiceEvents=[];for(const name of ['pointerdown','pointerup','keydown','input','change','dragstart','drop','blur'])window.addEventListener(name,e=>window.__practiceEvents.push({type:e.type,shape:e.target?.closest?.('.shape-tile')?.dataset.type,viewport:!!e.target?.closest?.('#viewport'),key:e.key,action:e.target?.closest?.('[data-action]')?.dataset.action,target:e.target?.id||e.target?.className||e.target?.tagName,trusted:e.isTrusted,value:['input','change'].includes(e.type)?String(e.target?.value??'').slice(0,80):undefined,warning:document.getElementById('practice-interaction-warning')?.textContent,warningWeight:document.getElementById('practice-interaction-warning')?getComputedStyle(document.getElementById('practice-interaction-warning')).fontWeight:null}),true);`);});
 const channel={on:(...args)=>process.on(...args),send(msg){
  if(msg.type==='result')void (async()=>{fs.writeFileSync(path.join(proof,'practice-child.png'),(await win.webContents.capturePage()).toPNG());const events=await win.webContents.executeJavaScript('window.__practiceEvents');fs.writeFileSync(path.join(proof,'practice-child.json'),JSON.stringify({result:msg.value,errors,external,events,overlayVisible:await win.webContents.executeJavaScript("!!document.getElementById('practice-overlay')?.getClientRects().length"),initialTempo:await win.webContents.executeJavaScript('window.__practiceInitialTempo'),uiBuildFrames:await win.webContents.executeJavaScript('window.__practiceUIBuildFrames'),tempo:await win.webContents.executeJavaScript("document.getElementById('practice-speed')?.value"),buildFrames:await win.webContents.executeJavaScript('window.__practiceBuildFrames'),interactionWarning:await win.webContents.executeJavaScript("document.getElementById('practice-interaction-warning')?.textContent")},null,2));process.send(msg);setTimeout(()=>{win.destroy();app.exit(0);},1000);})();
  else process.send(msg);
 }};
 require('../../backend/practice-child.cjs').installPracticeChild(win,{channel});
 await win.loadFile(entry,{query:{practice:'1'}});win.show();win.focus();
 const testTempo=Number(process.env.FORMNARO_TEST_TEMPO||0);if(testTempo>=10&&testTempo<=300){let adjusted=false;const timer=setInterval(async()=>{if(adjusted||win.isDestroyed())return;try{const box=await win.webContents.executeJavaScript('(()=>{const e=document.getElementById("practice-speed");if(!e||!e.getClientRects().length)return null;const r=e.getBoundingClientRect();return {left:r.left,top:r.top,width:r.width,height:r.height}})()');if(!box)return;adjusted=true;const x=Math.round(box.left+8+(testTempo-10)/290*(box.width-16)),y=Math.round(box.top+box.height/2);for(const type of ['mouseDown','mouseUp'])win.webContents.sendInputEvent({type,x,y,button:'left',clickCount:1});clearInterval(timer);}catch{}},50);win.on('closed',()=>clearInterval(timer));}
 let couplingCaptured=false;const couplingTimer=setInterval(async()=>{if(couplingCaptured||win.isDestroyed())return;try{const ready=await win.webContents.executeJavaScript("!!document.getElementById('joint-gears')?.open&&document.getElementById('joint-teeth-b')?.value==='30'");if(ready){couplingCaptured=true;fs.writeFileSync(path.join(proof,'coupling-dialog.png'),(await win.webContents.capturePage()).toPNG());clearInterval(couplingTimer);}}catch{}},150);win.on('closed',()=>clearInterval(couplingTimer));
 let capturing=false;const noticeTimer=setInterval(async()=>{if(capturing||win.isDestroyed())return;capturing=true;try{const active=await win.webContents.executeJavaScript("window.__practiceEvents?.some(e=>e.type==='pointerdown')&&document.getElementById('practice-interaction-warning')?.textContent.includes('Tempo, Pause und Stop')");if(!active){const building=await win.webContents.executeJavaScript("document.getElementById('practice-caption')?.textContent.startsWith('Live-Aufbau')");if(building&&!fs.existsSync(path.join(proof,'practice-live-build.png')))fs.writeFileSync(path.join(proof,'practice-live-build.png'),(await win.webContents.capturePage()).toPNG());}if(active){fs.writeFileSync(path.join(proof,'practice-running-warning.png'),(await win.webContents.capturePage()).toPNG());clearInterval(noticeTimer);}}catch{}finally{capturing=false;}},100);win.on('closed',()=>clearInterval(noticeTimer));
 let frameCapturing=false;const frameTimer=setInterval(async()=>{if(frameCapturing||win.isDestroyed())return;frameCapturing=true;try{const building=await win.webContents.executeJavaScript("document.getElementById('empty-hint')?.hidden&&window.__practiceUIBuildFrames?.some(f=>f.count>0&&f.count<3)");if(building){await new Promise(resolve=>setTimeout(resolve,200));fs.writeFileSync(path.join(proof,'practice-live-build.png'),(await win.webContents.capturePage()).toPNG());clearInterval(frameTimer);}}catch{}finally{frameCapturing=false;}},250);win.on('closed',()=>clearInterval(frameTimer));
});
